from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def calculate_nesting_level(group):
        max_nesting = 0
        current_nesting = 0
        for char in group:
            if char == '(':
                current_nesting += 1
                max_nesting = max(max_nesting, current_nesting)
            elif char == ')':
                current_nesting -= 1
        return max_nesting

    groups = paren_string.split()
    nesting_levels = [calculate_nesting_level(group) for group in groups]

    return nesting_levels
